5	const PROCESSING_FEE = 5;
6	
7	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
8	
9	const ITEM_BASE_PREMIUM: Record<string, number> = {
10	  sword: 100,
11	  amulet: 60,
12	  staff: 80,
13	  potion: 40,
14	  rune: 25,
15	  moonstone: 25,
16	};
17	
18	type Item = { type: string };
19	
20	type Step = { op: string; items: Item[] };
21	
22	type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
23	
24	const BLOCK_SIZE = 3;
25	
26	// A block is exactly BLOCK_SIZE items of the same type; 4 runes are not a block.
27	// Only rune blocks are forced so far, and only as a whole policy — hence the
28	// single constant rather than a per-type block price.
29	const RUNE_BLOCK_BASE_PREMIUM = 60;
30	
31	const isRuneBlock = (items: Item[]): boolean =>
32	  items.length === BLOCK_SIZE && items.every((item) => item.type === "rune");
33	
34	const policyBasePremium = (items: Item[]): number => {
35	  if (isRuneBlock(items)) return RUNE_BLOCK_BASE_PREMIUM;
36	
37	  return items.reduce((sum, item) => sum + ITEM_BASE_PREMIUM[item.type], 0);
38	};
39	
40	const quoteStep = (step: Step): QuoteResult => {
41	  const basePremium = policyBasePremium(step.items);
42	  // Deliberately additive, not `base * (1 + rate)`: the latter is the same in
43	  // exact arithmetic but not in binary floating point (100 * 1.1 is
44	  // 110.00000000000001), and Math.ceil turns that 1e-14 into a whole gold piece.
45	  const afterPercentageModifiers =
46	    basePremium + basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
47	
48	  // The fee is added after every percentage modifier, and only the final
49	  // premium is rounded — intermediates stay fractional.
50	  return { premium: Math.ceil(afterPercentageModifiers + PROCESSING_FEE) };
51	};
52	
53	export const runScenario = (scenario: Scenario): ScenarioResults => ({
54	  results: scenario.steps.map(quoteStep),
55	});
